def Rep (p : Nat) : Prop := ∃ q₁ ∈ Finset.range (p + 1), ∃ q₂ ∈ Finset.range (p + 1), Nat.Prime q₁ ∧ Nat.Prime q₂ ∧ (2 : Int) = (q₁ : Int) - (q₂ : Int)

def Twin (p : Nat) : Prop := ∃ q ∈ Finset.range (p + 1), Nat.Prime q ∧ Nat.Prime (q + 2) ∧ q + 2 ≤ p

def check : Bool := (Finset.Icc 5 20).all (fun p => decide (Rep p → Twin p))

